// Ported from osu.Game/Rulesets/Scoring/HitEvent.cs

import type { Vector2F } from '@fw/layout/Vector2F';
import type { HitObject } from '../objects/HitObject';
import type { HitResult } from './HitResult';

/** A HitEvent generated by the ScoreProcessor containing extra statistics around a HitResult. */
export class HitEvent {
  /**
   * @param timeOffset The offset from the end time of hitObject at which the event occurs: negative when early, positive when late.
   * @param gameplayRate The true gameplay rate at the time of the event.
   * @param result The HitResult.
   * @param hitObject The HitObject that triggered the event.
   * @param lastHitObject The previous HitObject.
   * @param position A position corresponding to the event (osu!: the cursor position at the hit, relative to the playfield).
   */
  constructor(
    readonly timeOffset: number,
    readonly gameplayRate: number | null,
    readonly result: HitResult,
    readonly hitObject: HitObject,
    readonly lastHitObject: HitObject | null,
    readonly position: Vector2F | null,
  ) {}

  /** Creates a new HitEvent with an optional positional offset. */
  with(positionOffset: Vector2F | null): HitEvent {
    return new HitEvent(this.timeOffset, this.gameplayRate, this.result, this.hitObject, this.lastHitObject, positionOffset);
  }
}
